// Dev tooling only (Node): mirrors every *.jsonl fixture in this folder into
// transcripts.ts, so `claude plugin test` (which has no file system) can hand
// the scanner the same lines. Run after editing a fixture:
//   node tests/fixtures/sync.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const names = readdirSync(here)
  .filter(name => name.endsWith('.jsonl'))
  .sort()
const entries = names.map(name => {
  const text = readFileSync(join(here, name), 'utf8')
  return `  ${JSON.stringify(name.slice(0, -'.jsonl'.length))}: ${JSON.stringify(text)},`
})
const out = [
  '// Generated by tests/fixtures/sync.mjs from the *.jsonl files beside it; do not edit.',
  '// The .jsonl files are the fixtures; this mirror exists because a plugin test',
  '// has no file system of its own and hands the scanner text through fs stubs.',
  'export const transcripts: Record<string, string> = {',
  ...entries,
  '}',
  '',
].join('\n')
writeFileSync(join(here, 'transcripts.ts'), out)
console.log(`wrote transcripts.ts with ${names.length} fixture(s): ${names.join(', ')}`)
